package bookbridge.ui;
import bookbridge.service.*;
import bookbridge.model.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.*;
import java.util.concurrent.ExecutionException;
public final class BookBridgeGUI extends JFrame {
 private final LibraryService service=new LibraryService();private final JTabbedPane tabs=new JTabbedPane();private final JLabel status=new JLabel("Ready");private final JProgressBar progress=new JProgressBar();
 private final DefaultTableModel catalog=model("ISBN","Title","Status"),members=model("ID","Name","Type"),loans=model("Loan ID","Member","ISBN","Due","Status"),reservations=model("ID","Member","ISBN","Status");
 private final JTextArea report=new JTextArea();private final java.util.List<JButton> controls=new ArrayList<>();
 private static DefaultTableModel model(String... headers){return new DefaultTableModel(headers,0){public boolean isCellEditable(int r,int c){return false;}};}
 public BookBridgeGUI(){super("BookBridge TSA4 - Library Management");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,680);setLocationRelativeTo(null);
  tabs.addTab("Catalog",catalogPanel());tabs.addTab("Members",memberPanel());tabs.addTab("Circulation",loanPanel());tabs.addTab("Reservations",reservationPanel());tabs.addTab("Reports",reportPanel());
  add(tabs,BorderLayout.CENTER);JPanel bottom=new JPanel(new BorderLayout(8,0));bottom.add(status,BorderLayout.CENTER);progress.setIndeterminate(true);progress.setVisible(false);bottom.add(progress,BorderLayout.EAST);add(bottom,BorderLayout.SOUTH);refreshAll();}
 private JPanel base(DefaultTableModel m){JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));p.add(new JScrollPane(new JTable(m)),BorderLayout.CENTER);return p;}
 private JButton button(JPanel bar,String text,Runnable action){JButton b=new JButton(text);controls.add(b);b.addActionListener(e->action.run());bar.add(b);return b;}
 private JPanel catalogPanel(){JPanel p=base(catalog),bar=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField search=new JTextField(20);bar.add(new JLabel("Search ISBN/title:"));bar.add(search);button(bar,"Search",()->load("Search catalog",()->service.books(search.getText()),rows->fill(catalog,rows.stream().map(b->new Object[]{b.isbn(),b.title(),b.status()}).toList())));button(bar,"Add Book",()->{
  String isbn=ask("ISBN"),title=isbn==null?null:ask("Title");if(title!=null)change("Add book",()->{service.addBook(isbn,title);return null;});});button(bar,"Refresh",this::refreshAll);p.add(bar,BorderLayout.NORTH);return p;}
 private JPanel memberPanel(){JPanel p=base(members),bar=new JPanel(new FlowLayout(FlowLayout.LEFT));button(bar,"Register Member",()->{String id=ask("Member ID"),name=id==null?null:ask("Full name");if(name==null)return;Object type=JOptionPane.showInputDialog(this,"Membership type","Register",JOptionPane.QUESTION_MESSAGE,null,Member.Type.values(),Member.Type.STUDENT);if(type!=null)change("Register member",()->{service.register(id,name,(Member.Type)type);return null;});});button(bar,"Refresh",this::refreshAll);p.add(bar,BorderLayout.NORTH);return p;}
 private JPanel loanPanel(){JPanel p=base(loans),bar=new JPanel(new FlowLayout(FlowLayout.LEFT));button(bar,"Issue Loan",()->{String member=ask("Member ID"),isbn=member==null?null:ask("ISBN"),days=isbn==null?null:ask("Loan days");if(days!=null)change("Issue loan",()->service.issue(member,isbn,Integer.parseInt(days.trim())));});button(bar,"Return Book",()->{String id=ask("Loan ID");if(id!=null&&JOptionPane.showConfirmDialog(this,"Return loan "+id+"?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)change("Return book",()->{service.returnBook(id);return null;});});button(bar,"Refresh",this::refreshAll);p.add(bar,BorderLayout.NORTH);return p;}
 private JPanel reservationPanel(){JPanel p=base(reservations),bar=new JPanel(new FlowLayout(FlowLayout.LEFT));button(bar,"Reserve",()->{String member=ask("Member ID"),isbn=member==null?null:ask("ISBN");if(isbn!=null)change("Reserve book",()->service.reserve(member,isbn));});button(bar,"Cancel Reservation",()->{String id=ask("Reservation ID");if(id!=null&&JOptionPane.showConfirmDialog(this,"Cancel reservation "+id+"?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)change("Cancel reservation",()->{service.cancel(Long.parseLong(id.trim()));return null;});});button(bar,"Process Next",()->{String isbn=ask("Returned ISBN to process");if(isbn!=null)change("Process reservation",()->service.processNextReservation(isbn));});button(bar,"Refresh",this::refreshAll);p.add(bar,BorderLayout.NORTH);return p;}
 private JPanel reportPanel(){JPanel p=new JPanel(new BorderLayout());report.setEditable(false);report.setFont(new Font(Font.MONOSPACED,Font.PLAIN,14));p.add(new JScrollPane(report),BorderLayout.CENTER);JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));button(bar,"Load Report",()->load("Load report",service::report,report::setText));p.add(bar,BorderLayout.NORTH);return p;}
 private String ask(String label){return JOptionPane.showInputDialog(this,label);}
 private interface Task<T>{T execute()throws Exception;}
 private <T> void load(String name,Task<T> task,java.util.function.Consumer<T> success){for(JButton b:controls)b.setEnabled(false);progress.setVisible(true);status.setText(name+" in progress...");
  new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return task.execute();}protected void done(){try{T result=get();success.accept(result);status.setText(name+" completed.");}catch(InterruptedException ex){Thread.currentThread().interrupt();status.setText("Interrupted");}catch(ExecutionException ex){Throwable cause=ex.getCause();status.setText("Error: "+cause.getMessage());JOptionPane.showMessageDialog(BookBridgeGUI.this,cause.getMessage(),"Operation failed",JOptionPane.ERROR_MESSAGE);}finally{progress.setVisible(false);for(JButton b:controls)b.setEnabled(true);}}}.execute();}
 private void change(String name,Task<?> task){load(name,task,x->{JOptionPane.showMessageDialog(this,name+" successful"+(x==null?"":": "+x));refreshAll();});}
 private static void fill(DefaultTableModel m,java.util.List<Object[]> rows){m.setRowCount(0);for(Object[] r:rows)m.addRow(r);}
 public void refreshAll(){load("Refresh catalog",()->service.books(""),rows->fill(catalog,rows.stream().map(b->new Object[]{b.isbn(),b.title(),b.status()}).toList()));load("Refresh members",service::members,rows->fill(members,rows.stream().map(m->new Object[]{m.id(),m.name(),m.type()}).toList()));load("Refresh loans",service::loans,rows->fill(loans,rows.stream().map(l->new Object[]{l.id(),l.memberId(),l.isbn(),l.dueDate(),l.status(java.time.LocalDate.now())}).toList()));load("Refresh reservations",service::reservations,rows->fill(reservations,rows.stream().map(r->new Object[]{r.id(),r.memberId(),r.isbn(),r.status()}).toList()));}
}
